package io.github.diodeme.ji.ai;

import java.net.URI;
import java.util.List;
import java.util.Map;

/** Versioned Host-owned provider connection profile. */
public record ProviderProfile(
        String id,
        ProviderProtocolFamily family,
        URI baseUrl,
        CredentialReference credential,
        List<SensitiveHeader> headers,
        ModelCatalog modelCatalog,
        String defaultModel,
        Map<String, Object> settings,
        long revision) {
    public ProviderProfile {
        if (id == null || id.isBlank()) throw new IllegalArgumentException("profile id must not be blank");
        if (family == null) throw new IllegalArgumentException("family must not be null");
        if (baseUrl == null || !baseUrl.isAbsolute() || baseUrl.getHost() == null) {
            throw new IllegalArgumentException("baseUrl must be an absolute HTTP(S) URI");
        }
        String scheme = baseUrl.getScheme();
        if (!"http".equalsIgnoreCase(scheme) && !"https".equalsIgnoreCase(scheme)) {
            throw new IllegalArgumentException("baseUrl must use HTTP or HTTPS");
        }
        if (baseUrl.getRawQuery() != null || baseUrl.getRawFragment() != null || baseUrl.getRawUserInfo() != null) {
            throw new IllegalArgumentException("baseUrl must not contain user info, query, or fragment");
        }
        if (credential == null) throw new IllegalArgumentException("credential must not be null");
        headers = List.copyOf(headers);
        if (modelCatalog == null) throw new IllegalArgumentException("modelCatalog must not be null");
        if (defaultModel == null || defaultModel.isBlank()) throw new IllegalArgumentException("defaultModel must not be blank");
        if (modelCatalog.find(defaultModel).isEmpty()) throw new IllegalArgumentException("defaultModel is absent from modelCatalog");
        settings = Map.copyOf(settings);
        if (revision < 0) throw new IllegalArgumentException("revision must be non-negative");
    }
}
